const isEvent    = key => key.startsWith("on");
const isProperty = key => key !== "children" && !isEvent(key);
const isGone     = (prev, next) => key => !(key in next);
const isNew      = (prev, next) => key => prev[key] !== next[key];

export function updateDom(dom, prevProps, nextProps) {
  // 1. purane/badle hue event listeners hatao
  Object.keys(prevProps)
    .filter(isEvent)
    .filter(key => !(key in nextProps) || isNew(prevProps, nextProps)(key))
    .forEach(key => dom.removeEventListener(key.toLowerCase().slice(2), prevProps[key]));

  // 2. gayab ho chuke props hatao
  Object.keys(prevProps).filter(isProperty).filter(isGone(prevProps, nextProps))
    .forEach(key => { dom[key] = ""; });

  // 3. naye ya badle hue props lagao
  Object.keys(nextProps).filter(isProperty).filter(isNew(prevProps, nextProps))
    .forEach(key => {
      if (key === "style" && typeof nextProps[key] === "object") {
        Object.assign(dom.style, nextProps[key]);
      } else {
        dom[key] = nextProps[key];
      }
    });

  // 4. naye event listeners lagao
  Object.keys(nextProps).filter(isEvent).filter(isNew(prevProps, nextProps))
    .forEach(key => dom.addEventListener(key.toLowerCase().slice(2), nextProps[key]));
}

