// src/mini-react.js
let currentTree = null;
let rootContainer = null;

export function mount(element, container) {
  rootContainer = container;
  currentTree = element;
  container.appendChild(createDom(element));
}

export function update(newTree) {
  reconcile(rootContainer, currentTree, newTree, 0);
  currentTree = newTree;
}

// createDom = wahi purana render(), par append nahi karta, sirf banata hai
function createDom(element) {
  const dom = element.type === "TEXT_ELEMENT"
    ? document.createTextNode("")
    : document.createElement(element.type);

  updateDom(dom, {}, element.props);
  element.dom = dom;                                     // <-- yaad rakha
  element.props.children.forEach(child => dom.appendChild(createDom(child)));
  return dom;
}

export function reconcile(parentDom, oldEl, newEl, index = 0) {
  // CASE 1 -- ADD
  if (!oldEl) {
    parentDom.appendChild(createDom(newEl));
    return;
  }

  // CASE 2 -- REMOVE
  if (!newEl) {
    parentDom.removeChild(parentDom.childNodes[index]);
    return;
  }

  // CASE 3 -- REPLACE (type badal gaya)
  if (oldEl.type !== newEl.type) {
    parentDom.replaceChild(createDom(newEl), parentDom.childNodes[index]);
    return;
  }

  // CASE 4 -- UPDATE (type same)
  const dom = oldEl.dom;
  newEl.dom = dom;                                    // identity yahan bachti hai
  updateDom(dom, oldEl.props, newEl.props);

  const oldKids = oldEl.props.children;
  const newKids = newEl.props.children;
  const n = Math.max(oldKids.length, newKids.length);
  for (let i = 0; i < n; i++) {
    reconcile(dom, oldKids[i], newKids[i], i);
  }
}

