function reconcileChildren(parentDom, oldKids, newKids) {
  // Agar kisi bhi bachche ke paas key nahi hai -> purana index-wala tarika
  const hasKeys = newKids.some(k => k && k.props.key != null);
  if (!hasKeys) {
    const n = Math.max(oldKids.length, newKids.length);
    for (let i = n - 1; i >= 0; i--) reconcile(parentDom, oldKids[i], newKids[i], i);
    return;
  }

  // 1. purane bachon ka map
  const oldByKey = new Map();
  oldKids.forEach(k => { if (k) oldByKey.set(k.props.key, k); });

  // 2. naye bachon pe loop -- match ya create
  const doms = [];
  for (const newKid of newKids) {
    const key = newKid.props.key;
    const oldKid = oldByKey.get(key);

    if (oldKid && oldKid.type === newKid.type) {
      newKid.dom = oldKid.dom;
      updateDom(newKid.dom, oldKid.props, newKid.props);
      reconcileChildren(newKid.dom, oldKid.props.children, newKid.props.children);
      oldByKey.delete(key);                 // ise bacha liya
    } else {
      newKid.dom = createDom(newKid);
    }
    doms.push(newKid.dom);
  }

  // 3. jo bach gaye purane -- hata do
  oldByKey.forEach(k => parentDom.removeChild(k.dom));

  // 4. order theek karo -- peeche se aage
  let next = null;
  for (let i = doms.length - 1; i >= 0; i--) {
    if (doms[i].nextSibling !== next) parentDom.insertBefore(doms[i], next);
    next = doms[i];
  }
}

