// hooks.js -- poora useState 20 line mein
let currentInstance = null;     // abhi kaunsa component render ho raha hai
let hookIndex = 0;

export function prepareToRender(instance) {
  currentInstance = instance;
  hookIndex = 0;
  instance.hooks = instance.hooks || [];
}

export function useState(initial) {
  const instance = currentInstance;
  const i = hookIndex++;

  if (instance.hooks[i] === undefined) {
    instance.hooks[i] = typeof initial === "function" ? initial() : initial;
  }

  const setState = (action) => {
    const prev = instance.hooks[i];
    const next = typeof action === "function" ? action(prev) : action;
    if (Object.is(prev, next)) return;        // kuch nahi badla -> re-render mat karo
    instance.hooks[i] = next;
    scheduleUpdate();                          // library ko batao
  };

  return [instance.hooks[i], setState];
}

