let effectQueue = [];

export function useEffect(fn, deps) {
  const instance = currentInstance;
  const i = hookIndex++;
  const prev = instance.hooks[i];

  const changed = !prev || !deps || !sameDeps(prev.deps, deps);

  instance.hooks[i] = { deps, cleanup: prev && prev.cleanup };

  if (changed) {
    effectQueue.push(() => {
      if (prev && prev.cleanup) prev.cleanup();       // purana saaf karo
      const cleanup = fn();                            // naya chalao
      instance.hooks[i].cleanup = typeof cleanup === "function" ? cleanup : null;
