// reconcileChildren -- ab purane fibers se compare bhi karta hai
function reconcileChildren(wipFiber, elements) {
  let index = 0;
  let oldFiber = wipFiber.alternate && wipFiber.alternate.child;
  let prevSibling = null;

  while (index < elements.length || oldFiber) {
    const element = elements[index];
    let newFiber = null;
    const sameType = oldFiber && element && element.type === oldFiber.type;

    if (sameType) {
      newFiber = {                                    // UPDATE
        type: oldFiber.type, props: element.props,
        dom: oldFiber.dom,                            // <-- DOM reuse (Phase 6 wali line!)
        return: wipFiber, alternate: oldFiber,
        effectTag: "UPDATE"
      };
    }
    if (element && !sameType) {
      newFiber = {                                    // PLACEMENT
        type: element.type, props: element.props,
        dom: null, return: wipFiber, alternate: null,
        effectTag: "PLACEMENT"
      };
    }
    if (oldFiber && !sameType) {
      oldFiber.effectTag = "DELETION";                // DELETION
      deletions.push(oldFiber);                       // alag list mein
    }

    if (oldFiber) oldFiber = oldFiber.sibling;
    if (index === 0) wipFiber.child = newFiber;
    else if (element) prevSibling.sibling = newFiber;
    if (newFiber) prevSibling = newFiber;
    index++;
  }
}

function commitRoot() {
  deletions.forEach(commitWork);        // pehle deletions
  commitWork(wipRoot.child);
  currentRoot = wipRoot;                 // <-- SWAP
  wipRoot = null;
  flushEffects();                        // effects commit ke baad
}

function commitWork(fiber) {
  if (!fiber) return;

  // DOM wala parent dhundo (components ka apna DOM nahi hota)
  let domParentFiber = fiber.return;
  while (domParentFiber && !domParentFiber.dom) domParentFiber = domParentFiber.return;
  const domParent = domParentFiber.dom;

  if (fiber.effectTag === "PLACEMENT" && fiber.dom) {
    domParent.appendChild(fiber.dom);
  } else if (fiber.effectTag === "UPDATE" && fiber.dom) {
    updateDom(fiber.dom, fiber.alternate.props, fiber.props);
  } else if (fiber.effectTag === "DELETION") {
    commitDeletion(fiber, domParent);
    return;                              // bachon mein mat jao
  }

  commitWork(fiber.child);
  commitWork(fiber.sibling);
}

function commitDeletion(fiber, domParent) {
  runCleanups(fiber);                    // useEffect cleanups
  if (fiber.dom) domParent.removeChild(fiber.dom);
  else commitDeletion(fiber.child, domParent);   // component -- neeche dekho
}

