function pushEffect(fn, deps, queue) {
  const old = getHook();
  const changed = !old || !deps || !sameDeps(old.deps, deps);
  const hook = { deps, cleanup: old ? old.cleanup : null, tag: "effect" };
  wipFiber.hooks.push(hook);
  if (changed) queue.push(() => {
    if (hook.cleanup) hook.cleanup();
    const c = fn();
    hook.cleanup = typeof c === "function" ? c : null;
  });
}

