// Simple delegation -- 25 line
const handlerMap = new WeakMap();          // domNode -> { click: fn, input: fn }
const attachedTypes = new Set();

export function setEventHandler(dom, type, handler) {
  let map = handlerMap.get(dom);
  if (!map) { map = {}; handlerMap.set(dom, map); }
  if (handler) map[type] = handler; else delete map[type];

  if (!attachedTypes.has(type)) {
    attachedTypes.add(type);
    rootContainer.addEventListener(type, dispatch);
  }
}

function dispatch(nativeEvent) {
  const type = nativeEvent.type;
  const syntheticEvent = {
    type,
    target: nativeEvent.target,
    nativeEvent,
    _stopped: false,
    stopPropagation() { this._stopped = true; nativeEvent.stopPropagation(); },
    preventDefault() { nativeEvent.preventDefault(); }
  };

  // target se upar chalte jao -- khud bubbling
  let node = nativeEvent.target;
  while (node && node !== rootContainer.parentNode) {
    const map = handlerMap.get(node);
    if (map && map[type]) {
      map[type](syntheticEvent);
      if (syntheticEvent._stopped) break;
    }
    node = node.parentNode;
  }
}

